// UserDashboard is an async server component. It fetches user-specific data
// that may change on every request, so the fetch is opted out of the
// Next.js fetch cache via `cache: 'no-store'` to keep it fully dynamic.
async function getUserPreferences() {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return res.json()
  } catch {
    // Return mock data for build time / when the API is unavailable.
    return {
      theme: 'system',
      notifications: {
        email: true,
        push: false,
      },
      language: 'en',
    }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>User dashboard content goes here</p>
      <dl>
        <dt>Theme</dt>
        <dd>{preferences.theme}</dd>

        <dt>Language</dt>
        <dd>{preferences.language}</dd>

        <dt>Email notifications</dt>
        <dd>{preferences.notifications?.email ? 'On' : 'Off'}</dd>

        <dt>Push notifications</dt>
        <dd>{preferences.notifications?.push ? 'On' : 'Off'}</dd>
      </dl>
    </div>
  )
}

